/**
 * Real-OCR overlay check for bench/pdf/scan.pdf page 1.
 *
 * Renders the image-only scan at several DPIs in Chromium, runs the shipped PP-OCRv6 pipeline
 * with a chosen preprocessing/detection/recognition variant, feeds the result through the
 * reader's OCR layout and placement, and measures what a reader would see.
 *
 * Ground truth is the committed, reading-ordered transcription of the very same document:
 * bench/pdf/scan-p1.gt.txt, generated by scripts/bench/build-scan-gt.ts. paper.pdf's print
 * text layer is deliberately NOT used here: it has different margins and page breaks.
 *
 *   pnpm bench:pdf:scan:ocr --variants default-1600,gray+contrast --label experiment-1
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

import { loadPairing, decodePngImage, type Pairing } from './ocr-engine.ts';
import { applyOcrPreprocess, type OcrPreprocessStep } from '../../src/engine/ocr/preprocess.ts';
import { OcrPipeline } from '../../src/engine/ocr/pipeline.ts';
import { startStaticServer } from './static.ts';
import {
  characterErrorRate,
  lineOrderAccuracy,
  normalizeOcrText,
  recognitionCoverage,
  wordErrorRate,
} from './ocr-metrics.ts';
import { extractPage } from '../../src/pdf/extract.ts';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const OUT = join(ROOT, 'bench/results/scan-ocr');
const requireModule = createRequire(import.meta.url).resolve;
const VIEWER = '/scripts/bench/pdf-quality-view.html';
const PDF = 'bench/pdf/scan.pdf';
const GT = 'bench/pdf/scan-p1.gt.txt';

const flagDump = process.argv.includes('--dump');
const flagShots = process.argv.includes('--shots');
const SHOTS = join(ROOT, 'bench/results/screenshots/final');

function option(name: string, fallback: string): string {
  const index = process.argv.indexOf(name);
  return index >= 0 && process.argv[index + 1] !== undefined
    ? (process.argv[index + 1] ?? fallback)
    : fallback;
}

interface Variant {
  readonly id: string;
  readonly scale: number;
  readonly steps?: readonly OcrPreprocessStep[];
  readonly maxSide: number;
  readonly recognition?: { height: number; maxWidth: number };
  readonly detection?: Record<string, number>;
}

const VARIANTS: readonly Variant[] = [
  { id: 'baseline-1x', scale: 1, maxSide: 960 },
  { id: 'dpi200', scale: 4 / 3, maxSide: 1280 },
  // The pre-change shipped path: reader renders at 2x, detector capped at 960px.
  { id: 'shipped-baseline', scale: 2, maxSide: 960 },
  // Current shipped default: the reader renders at 2x and detects at maxSide 1600.
  { id: 'default-1600', scale: 2, maxSide: 1600 },
  { id: 'dpi300', scale: 2, maxSide: 1920 },
  { id: 'sauvola', scale: 1, steps: ['sauvola'], maxSide: 960 },
  { id: 'dpi200+sauvola', scale: 4 / 3, steps: ['sauvola'], maxSide: 1280 },
  { id: 'dpi200+gray', scale: 4 / 3, steps: ['grayscale'], maxSide: 1280 },
  { id: 'gray+contrast', scale: 4 / 3, steps: ['grayscale', 'contrast'], maxSide: 1280 },
  { id: 'gray+contrast-1600', scale: 2, steps: ['grayscale', 'contrast'], maxSide: 1600 },
  { id: 'contrast', scale: 4 / 3, steps: ['contrast'], maxSide: 1280 },
  { id: 'otsu', scale: 4 / 3, steps: ['otsu'], maxSide: 1280 },
  { id: 'denoise', scale: 4 / 3, steps: ['denoise'], maxSide: 1280 },
  { id: 'trim', scale: 4 / 3, steps: ['trim-border'], maxSide: 1280 },
  { id: 'box-0.35', scale: 4 / 3, maxSide: 1280, detection: { boxThreshold: 0.35 } },
  { id: 'box-0.55', scale: 4 / 3, maxSide: 1280, detection: { boxThreshold: 0.55 } },
  { id: 'unclip-1.8', scale: 4 / 3, maxSide: 1280, detection: { unclipRatio: 1.8 } },
];

/**
 * Aligns recognized lines to the nearest unused reference line by word overlap before scoring
 * CER/WER. CER then measures character recognition, not the reader\'s column ordering; the
 * ordering is reported separately by `line order` on the unmodified product output.
 */
function alignToReference(reference: readonly string[], hypothesis: readonly string[]): string[] {
  const words = (text: string): Set<string> =>
    new Set(normalizeOcrText(text).split(' ').filter(Boolean));
  const pool = reference.map((text, index) => ({ index, words: words(text), used: false }));
  const scored = hypothesis.map((text, index) => {
    const source = words(text);
    let best: (typeof pool)[number] | null = null;
    let bestScore = 0;
    for (const candidate of pool) {
      if (candidate.used) continue;
      let shared = 0;
      for (const word of source) if (candidate.words.has(word)) shared += 1;
      const score = shared / Math.max(1, source.size, candidate.words.size);
      if (score > bestScore) {
        best = candidate;
        bestScore = score;
      }
    }
    return { index, text, best, bestScore, rank: reference.length + index };
  });
  for (const item of [...scored].sort((left, right) => right.bestScore - left.bestScore)) {
    if (item.best && item.bestScore >= 0.3 && !item.best.used) {
      item.best.used = true;
      item.rank = item.best.index;
    }
  }
  return [...scored].sort((left, right) => left.rank - right.rank).map((item) => item.text);
}
async function loadPdf<T>(name: string): Promise<T> {
  return (await import(fileURLToPath(new URL('../../src/pdf/' + name, import.meta.url)))) as T;
}

interface Layout {
  blocks: Array<{
    text: string;
    role: string;
    box: object;
    room: object;
    fontSize: number;
    lineHeight: number;
    column: number;
    advance: number;
    writing: number;
    lines: unknown[];
  }>;
  skipped: Array<{ text: string; role: string; box: object }>;
  obstacles: object[];
  bodySize: number;
}

async function renderPage(
  page: import('@playwright/test').Page,
  origin: string,
  scale: number,
): Promise<{ png: Buffer; width: number; height: number }> {
  const info = (await page.evaluate(
    async (data) => {
      await (
        globalThis as unknown as {
          __renderPdf: (value: {
            url: string;
            page: number;
            scale: number;
            overlays: unknown[];
          }) => Promise<unknown>;
        }
      ).__renderPdf({ url: data.url, page: 1, scale: data.scale, overlays: [] });
      const canvas = document.querySelector<HTMLCanvasElement>('#sheet canvas');
      return { width: canvas?.width ?? 0, height: canvas?.height ?? 0 };
    },
    { url: origin + '/' + PDF, scale },
  )) as { width: number; height: number };
  const png = await page.locator('#sheet canvas').screenshot();
  return { png, width: info.width, height: info.height };
}

async function main(): Promise<void> {
  await mkdir(OUT, { recursive: true });
  const label = option('--label', '');
  const pairing = option('--pairing', 'tiny_det+small_rec') as Pairing;
  const selectedIds = option('--variants', '').split(',').filter(Boolean);
  const variants = VARIANTS.filter(
    (variant) => selectedIds.length === 0 || selectedIds.includes(variant.id),
  );
  if (variants.length === 0) throw new Error('No matching variants');
  const reference = (await readFile(resolve(ROOT, GT), 'utf8')).trim();
  const referenceLines = reference.split('\n');
  const server = await startStaticServer({ directory: ROOT, isolated: false });
  const browser = await chromium.launch({
    executablePath: process.env.CHROME_PATH ?? '/usr/local/bin/google-chrome',
    headless: true,
    args: ['--no-sandbox'],
  });
  const loaded = await loadPairing(pairing);
  const pdfjsPath = requireModule('pdfjs-dist/legacy/build/pdf.mjs');
  const pdfjs = await import(pdfjsPath);
  // The raster viewer scales the PDF page's own MediaBox. Mapping quads onto Letter here would
  // stretch the scan's x axis and squash its y axis, so read the size from the loaded page.
  const scanBytes = await readFile(resolve(ROOT, PDF));
  const scanDoc = await pdfjs.getDocument({
    data: new Uint8Array(scanBytes),
    useSystemFonts: false,
  }).promise;
  const scanPage = await scanDoc.getPage(1);
  const viewport = scanPage.getViewport({ scale: 1 });
  const pageWidth = viewport.width;
  const pageHeight = viewport.height;
  await scanDoc.destroy();
  console.log('scan.pdf page 1 viewport: ' + pageWidth + ' x ' + pageHeight + ' pt');
  // Document why paper.pdf is not the GT: it is a print render with different page breaks.
  const paperBytes = await readFile(resolve(ROOT, 'bench/pdf/paper.pdf'));
  const paperDoc = await pdfjs.getDocument({ data: new Uint8Array(paperBytes) }).promise;
  const printLines = (await extractPage(await paperDoc.getPage(1), 0, pdfjs.OPS)).lines.length;
  await paperDoc.destroy();
  console.log('paper.pdf p1 print lines (NOT used as scan GT): ' + printLines);
  const { ocrResultToPageLayout, ocrResultToTextLines } = await loadPdf<{
    ocrResultToPageLayout: (
      result: unknown,
      options: {
        pageIndex: number;
        pageWidth: number;
        pageHeight: number;
        imageWidth: number;
        imageHeight: number;
      },
    ) => Layout;
    ocrResultToTextLines: (
      result: unknown,
      options: {
        pageIndex: number;
        pageWidth: number;
        pageHeight: number;
        imageWidth: number;
        imageHeight: number;
      },
    ) => Array<{ text: string }>;
  }>('ocr.ts');
  const { placePage, paintedCoverOverlaps } = await loadPdf<{
    placePage: (request: object) => Array<{
      paint: boolean;
      drawn: object | null;
      translation: string;
      fit: { fontSize: number } | null;
      block: {
        text: string;
        role: string;
        box: { x: number; y: number; width: number; height: number };
        fontSize: number;
      };
    }>;
    paintedCoverOverlaps: (placed: unknown[], pageWidth: number) => number;
  }>('place.ts');
  const { pageMetrics } = await loadPdf<{
    pageMetrics: (
      layout: Layout,
      placed: unknown[],
      page: object,
    ) => {
      crossColumnCovers: number;
      proseCovered: number;
      overlapPairs: number;
      overflow: number;
    };
  }>('metrics.ts');
  const modelBytes = loaded.models.reduce((sum, model) => sum + model.size, 0);
  const report: object[] = [];
  try {
    const page = await browser.newPage({ viewport: { width: 1200, height: 1500 } });
    await page.goto(server.origin + VIEWER);
    await page.waitForFunction('window.__pdfReady === true', null, { timeout: 20_000 });
    for (const variant of variants) {
      const rendered = await renderPage(page, server.origin, variant.scale);
      const path = join(OUT, 'raster-' + variant.id + '.png');
      await writeFile(path, rendered.png);
      const image = await decodePngImage(path);
      const preprocessed = applyOcrPreprocess(image, variant.steps ?? [], 1);
      const pipeline = new OcrPipeline({
        runner: loaded.runner,
        dictionary: loaded.dictionary,
        useSpaceChar: true,
        detection: { ...loaded.detection, ...variant.detection },
        detectionPreprocess: { maxSide: variant.maxSide, multiple: 32 },
        recognitionPreprocess: variant.recognition ?? { height: 48, maxWidth: 4096 },
      });
      const started = performance.now();
      const result = await pipeline.run(preprocessed.image);
      const ms = performance.now() - started;
      // Keep the engine\'s own reading-line grouping: it was computed on the detector image.
      // Re-grouping after mapping quads into page points changes the absolute-height tolerances
      // and merges the two body columns into single lines. ocrResultToTextLines scales by the
      // image size itself, so the original result is the correct input here.
      const options = {
        pageIndex: 0,
        pageWidth,
        pageHeight,
        imageWidth: preprocessed.image.width,
        imageHeight: preprocessed.image.height,
      };
      // Score the reader's final reading order, not raw detector order: groupReadingLines
      // assigns a global column first, while ocrResultToTextLines restores spanning bands.
      const readLines = ocrResultToTextLines(result, options);
      const hypothesisLines = readLines.map((line) => line.text);
      const aligned = alignToReference(referenceLines, hypothesisLines);
      const hypothesis = aligned.join('\n');
      const layout = ocrResultToPageLayout(result, options);
      await writeFile(join(OUT, 'text-' + variant.id + '.txt'), hypothesis + '\n');
      if (flagDump) {
        await writeFile(
          join(OUT, 'regions-' + variant.id + '.json'),
          JSON.stringify(
            {
              regions: result.regions.map((region) => ({
                text: region.text,
                bounds: {
                  left: Math.min(...region.quad.map((point) => preprocessed.mapBack(point).x)),
                  right: Math.max(...region.quad.map((point) => preprocessed.mapBack(point).x)),
                  top: Math.min(...region.quad.map((point) => preprocessed.mapBack(point).y)),
                  bottom: Math.max(...region.quad.map((point) => preprocessed.mapBack(point).y)),
                },
              })),
              lines: result.lines.map((line) => line.items.map((item) => item.text)),
            },
            null,
            2,
          ),
        );
      }
      const placed = placePage({
        layout,
        translationOf: (block: { text: string }) => block.text.replace(/[A-Za-z]+/gu, () => '語'),
        target: 'ja',
        measure: (_block: unknown, text: string, size: number) => text.length * size * 0.7,
        pageHeight,
        pageWidth,
      });
      const metrics = pageMetrics(layout, placed, {
        x: 0,
        y: 0,
        width: pageWidth,
        height: pageHeight,
      });
      const overlaps = paintedCoverOverlaps(placed, pageWidth);
      if (flagShots && variant.id === 'default-1600') {
        await mkdir(SHOTS, { recursive: true });
        const overlays = placed.map((entry) => ({
          source: entry.block.text.replace(/\s+/gu, ' ').slice(0, 60),
          role: entry.block.role,
          paint: entry.paint,
          translation: entry.translation.replace(/\s+/gu, ' ').slice(0, 400),
          fontSize: entry.fit?.fontSize ?? entry.block.fontSize,
          box: entry.drawn ?? entry.block.box,
        }));
        await page.evaluate(
          async (data) => {
            await (
              globalThis as unknown as {
                __renderPdf: (value: {
                  url: string;
                  page: number;
                  scale: number;
                  overlays: unknown[];
                }) => Promise<unknown>;
              }
            ).__renderPdf(data);
          },
          { url: server.origin + '/' + PDF, page: 1, scale: 1.25, overlays },
        );
        await page.locator('#sheet').screenshot({ path: join(SHOTS, 'scan-p1-real-ocr.png') });
      }
      const record = {
        variant: variant.id,
        pairing,
        ms,
        modelBytes,
        cer: characterErrorRate(reference, hypothesis).rate,
        wer: wordErrorRate(reference, hypothesis).rate,
        order: lineOrderAccuracy(referenceLines, hypothesisLines).accuracy,
        covered: recognitionCoverage(reference, hypothesis),
        lines: readLines.length,
        blocks: layout.blocks.length,
        skipped: layout.skipped.length,
        crossColumnCovers: metrics.crossColumnCovers,
        overlapPairs: Math.max(metrics.overlapPairs, overlaps),
        overflow: metrics.overflow,
        text: hypothesis.slice(0, 200),
      };
      report.push(record);
      console.log(JSON.stringify(record));
    }
    await page.close();
  } finally {
    await loaded.release();
    await browser.close();
    await server.close();
  }
  const header = [
    '| approach | pairing | CER | WER | line order | coverage | cross-column | ms/page | model bytes | lines | blocks | skipped |',
    '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |',
  ].join('\n');
  const markdown =
    [
      '# scan.pdf page 1 real-OCR overlay',
      '',
      'Ground truth: `bench/pdf/scan-p1.gt.txt` (reading-ordered transcription of the scan raster).',
      'CER/WER are scored on content-aligned lines (recognition accuracy); `line order` scores',
      'the product output order separately. `coverage` is word-level LCS against the GT.',
      '',
      header,
      ...report.map((entry) => {
        const r = entry as Record<string, number | string>;
        return (
          '| ' +
          r.variant +
          ' | ' +
          r.pairing +
          ' | ' +
          Number(r.cer).toFixed(3) +
          ' | ' +
          Number(r.wer).toFixed(3) +
          ' | ' +
          Number(r.order).toFixed(3) +
          ' | ' +
          Number(r.covered).toFixed(3) +
          ' | ' +
          r.crossColumnCovers +
          ' | ' +
          Number(r.ms).toFixed(0) +
          ' | ' +
          r.modelBytes +
          ' | ' +
          r.lines +
          ' | ' +
          r.blocks +
          ' | ' +
          r.skipped +
          ' |'
        );
      }),
    ].join('\n') + '\n';
  await writeFile(join(OUT, 'report.json'), JSON.stringify(report, null, 2) + '\n');
  await writeFile(join(OUT, 'report.md'), markdown);
  if (label) {
    await writeFile(join(OUT, label + '.json'), JSON.stringify(report, null, 2) + '\n');
    await writeFile(join(OUT, label + '.md'), markdown);
  }
  console.log(markdown);
}
void main().catch((error: unknown) => {
  console.error(error instanceof Error ? (error.stack ?? error.message) : String(error));
  process.exitCode = 1;
});
